INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (1,'Apple Scab','مرض جرب التفاح','A fungal disease of apple caused by Venturia inaequalis that infects young leaves and fruit during cool wet weather.','مرض فطري يصيب التفاح تسببه Venturia inaequalis ويظهر غالباً مع الجو البارد والرطب.','Olive-brown velvety spots on leaves, cracked scabby fruit lesions, early leaf drop.','بقع زيتونية بنية مخملية على الأوراق، تشققات وقشور على الثمار، وتساقط مبكر للأوراق.','Remove fallen leaves, prune for air flow, use resistant cultivars, and apply labeled protectant fungicides during wet periods.','إزالة الأوراق المتساقطة، التقليم لزيادة التهوية، زراعة أصناف مقاومة، واستخدام مبيدات فطرية وقائية مسجلة عند الرطوبة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (2,'Black Rot','مرض العفن الأسود','A fungal disease that attacks fruit, leaves, and branches, commonly associated with dead wood and old cankers.','مرض فطري يصيب الثمار والأوراق والأفرع وغالباً يرتبط بالأخشاب الميتة والتقرحات القديمة.','Circular leaf spots with dark margins, black rotted fruit, cankers on twigs or branches.','بقع دائرية على الأوراق بحواف داكنة، تعفن أسود في الثمار، وتقرحات على الأفرع.','Prune and destroy infected wood and mummified fruit, improve sanitation, and apply recommended fungicides when risk is high.','تقليم وحرق الأفرع والثمار المصابة، تحسين النظافة الزراعية، ورش مبيدات فطرية موصى بها عند ارتفاع خطر الإصابة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (3,'Cedar Apple Rust','مرض صدأ التفاح الأرزّي','A rust fungus disease that alternates between apple and juniper or cedar hosts.','مرض صدأ فطري يحتاج غالباً إلى عائلين هما التفاح والعرعر أو الأرز.','Bright orange leaf spots, yellow halos, fruit spots, and orange spore structures on leaf undersides.','بقع برتقالية لامعة على الأوراق، هالات صفراء، بقع على الثمار، وتراكيب بوغية برتقالية أسفل الورقة.','Remove nearby infected junipers if possible, plant resistant apples, and use preventive fungicides before and during early infection periods.','إزالة نباتات العرعر المصابة القريبة إن أمكن، زراعة أصناف مقاومة، واستخدام مبيدات وقائية قبل وأثناء بداية العدوى.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (4,'Blight Leaf Disease','مرض لفحة الأوراق','A leaf blight condition where pathogens rapidly kill leaf tissue, especially under humid conditions.','مرض لفحة أوراق يسبب موتاً سريعاً لأنسجة الورقة خصوصاً في الأجواء الرطبة.','Large brown dead areas, yellowing around lesions, leaf curling, and premature defoliation.','مساحات بنية ميتة كبيرة، اصفرار حول البقع، التفاف الأوراق، وتساقطها مبكراً.','Remove infected leaves, avoid overhead irrigation, increase spacing, and use suitable fungicide or bactericide according to the cause.','إزالة الأوراق المصابة، تجنب الري بالرش، زيادة المسافات والتهوية، واستخدام مبيد فطري أو بكتيري مناسب حسب السبب.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (5,'Shot Hole','مرض الثقوب الطلقية','A disease, often fungal or bacterial, causing small lesions that fall out and leave holes in leaves.','مرض قد يكون فطرياً أو بكتيرياً يسبب بقعاً صغيرة تسقط من الورقة وتترك ثقوباً.','Small purple or brown spots that drop out, ragged leaves, twig lesions, and reduced vigor.','بقع صغيرة أرجوانية أو بنية تسقط لاحقاً، أوراق مثقبة، إصابات على الأفرع، وضعف نمو النبات.','Collect diseased leaves, prune infected shoots, avoid wet foliage, and apply copper or labeled fungicides during dormancy or early growth.','جمع الأوراق المصابة، تقليم الأفرع المصابة، تجنب بلل الأوراق، واستخدام النحاس أو مبيد مسجل في السكون أو بداية النمو.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (6,'Anthracnose','مرض الأنثراكنوز','A group of fungal diseases that cause sunken lesions on leaves, stems, flowers, or fruit.','مجموعة أمراض فطرية تسبب بقعاً غائرة على الأوراق والسيقان والأزهار أو الثمار.','Dark sunken spots, leaf blight, twig dieback, fruit rot, and pink or orange spore masses in wet weather.','بقع داكنة غائرة، لفحة أوراق، موت أطراف، تعفن ثمار، وكتل بوغية وردية أو برتقالية مع الرطوبة.','Prune infected tissue, remove plant debris, improve air movement, and apply labeled fungicides before rainy periods.','تقليم الأنسجة المصابة، إزالة المخلفات، تحسين التهوية، ورش مبيدات فطرية مسجلة قبل فترات المطر.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (7,'Bed Bugs Disease','مرض بقّ الفراش','Damage caused by bed bug-like sucking insects feeding on plant tissues or fruits in some crops.','ضرر ناتج عن حشرات ماصة تشبه بق الفراش تتغذى على أنسجة النبات أو الثمار في بعض المحاصيل.','Small feeding punctures, yellow speckling, distorted tissues, reduced quality, and possible secondary infection.','نقاط تغذية صغيرة، تبقع أصفر، تشوه الأنسجة، انخفاض جودة المحصول، واحتمال عدوى ثانوية.','Monitor plants, remove weeds and hiding places, use insect-proof sanitation, and apply selective insecticides only when needed.','مراقبة النباتات، إزالة الأعشاب وأماكن الاختباء، تحسين النظافة، واستخدام مبيدات حشرية انتقائية عند الحاجة فقط.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (8,'Early Blight Disease','مرض اللفحة المبكرة','A fungal disease mainly caused by Alternaria species that affects older leaves and sometimes stems and fruit.','مرض فطري غالباً تسببه أنواع Alternaria ويصيب الأوراق القديمة وأحياناً السيقان والثمار.','Brown spots with concentric rings, yellowing leaves, stem lesions, and fruit spots near the stem end.','بقع بنية بحلقات متداخلة، اصفرار الأوراق، بقع على الساق، وإصابات على الثمار قرب العنق.','Rotate crops, remove infected debris, mulch to reduce soil splash, and apply preventive fungicides when conditions favor disease.','اتباع دورة زراعية، إزالة المخلفات المصابة، استخدام الملش لتقليل رذاذ التربة، ورش مبيد وقائي عند ملاءمة الظروف.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (9,'Fruit Borer Disease','مرض حفّار الثمار','Damage caused by larvae boring into fruits, making them unmarketable and prone to rot.','ضرر تسببه يرقات تحفر داخل الثمار فتجعلها غير صالحة للتسويق وأكثر عرضة للتعفن.','Entry holes, frass near holes, internal feeding tunnels, fruit drop, and secondary rotting.','ثقوب دخول، فضلات حشرية قرب الثقوب، أنفاق داخلية، تساقط الثمار، وتعفن ثانوي.','Remove infested fruit, use pheromone traps, bag fruits where practical, conserve natural enemies, and apply timed insecticides.','إزالة الثمار المصابة، استخدام مصائد فرمونية، تغليف الثمار عند الإمكان، حماية الأعداء الحيوية، والرش في التوقيت المناسب.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (10,'Hooded Hopper Insect Disease','مرض حشرة النطاط المقنّع','Injury caused by sap-sucking leafhoppers that weaken plants and may transmit pathogens.','ضرر ناتج عن نطاطات ماصة للعصارة تضعف النبات وقد تنقل مسببات مرضية.','Leaf yellowing, curling, stippling, sticky honeydew, poor growth, and hopper insects on leaf undersides.','اصفرار والتفاف الأوراق، تنقيط خفيف، إفرازات عسلية، ضعف نمو، ووجود الحشرات أسفل الورقة.','Control weeds, monitor with traps, encourage predators, and use systemic or contact insecticides according to threshold.','مكافحة الأعشاب، المراقبة بالمصائد، تشجيع المفترسات، واستخدام مبيد جهازي أو بالملامسة حسب شدة الإصابة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (11,'Leaf Insect Pest Disease','مرض آفات حشرات الأوراق','General leaf damage caused by chewing or sucking insects that reduce photosynthesis.','ضرر عام للأوراق بسبب حشرات قارضة أو ماصة يقلل قدرة النبات على البناء الضوئي.','Holes, skeletonized leaves, yellow speckles, curled leaves, frass, and visible larvae or insects.','ثقوب، تعرية نصل الورقة، تنقيط أصفر، التفاف الأوراق، فضلات حشرية، ووجود يرقات أو حشرات.','Handpick when light, remove weeds, use nets or traps, release beneficial insects, and apply targeted insecticides if needed.','الجمع اليدوي عند الإصابة الخفيفة، إزالة الأعشاب، استخدام الشبك أو المصائد، دعم الأعداء الحيوية، والرش الموجه عند الحاجة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (12,'Stem Borer Disease','مرض حفّار الساق','Insect larval damage in which borers tunnel inside stems and disrupt water and nutrient flow.','ضرر يرقات حشرية تحفر داخل الساق وتعيق انتقال الماء والغذاء.','Wilting shoots, holes in stems, frass, weak stems, lodging, and dead growing tips.','ذبول الأفرع، ثقوب في الساق، فضلات حشرية، ضعف الساق، رقاد النبات، وموت القمم النامية.','Remove and destroy bored stems, rotate crops, use pheromone traps, and apply insecticides before larvae enter stems.','إزالة وحرق السيقان المصابة، اتباع دورة زراعية، استخدام مصائد فرمونية، والرش قبل دخول اليرقات إلى الساق.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (13,'Alternaria Leaf Spot','مرض تبقع أوراق الألترناريا','A fungal leaf spot disease caused by Alternaria species, common in warm humid conditions.','مرض بقع ورقية فطري تسببه أنواع Alternaria ويكثر في الجو الدافئ الرطب.','Round brown to black spots with concentric rings, yellow halos, leaf blight, and defoliation.','بقع دائرية بنية إلى سوداء بحلقات متداخلة، هالات صفراء، لفحة، وتساقط الأوراق.','Use clean seed, remove crop residue, avoid overhead irrigation, rotate crops, and apply labeled fungicides.','استخدام بذور سليمة، إزالة بقايا المحصول، تجنب الري بالرش، تدوير المحاصيل، واستخدام مبيدات فطرية مسجلة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (14,'Bacterial Spot Rot','مرض العفن البقعي البكتيري','A bacterial disease causing water-soaked spots and rotting on leaves, stems, or fruit.','مرض بكتيري يسبب بقعاً مائية وتعفناً على الأوراق أو السيقان أو الثمار.','Water-soaked spots, greasy lesions, soft rot, fruit cracking, and bacterial ooze in wet weather.','بقع مائية، آفات دهنية، تعفن طري، تشقق الثمار، وإفراز بكتيري مع الرطوبة.','Use disease-free seed, avoid working wet plants, improve drainage, remove infected tissue, and apply copper-based bactericides.','استخدام بذور خالية من المرض، تجنب ملامسة النباتات وهي مبللة، تحسين الصرف، إزالة الأجزاء المصابة، ورش مركبات النحاس.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (15,'Cabbage Aphid Colony','مرض مستعمرة منّ الملفوف','Infestation by grey-green aphids that form dense colonies on brassica leaves and heads.','إصابة بحشرات المن الرمادية الخضراء التي تكون مستعمرات كثيفة على أوراق ورؤوس الكرنب.','Curled leaves, sticky honeydew, sooty mold, stunted plants, and clusters of aphids on new growth.','التفاف الأوراق، إفرازات عسلية، عفن هبابي، تقزم النبات، وتجمعات من المن على النموات الحديثة.','Encourage lady beetles and lacewings, wash colonies off, remove weeds, and use insecticidal soap or selective aphicides.','تشجيع الدعسوقة وأسد المن، غسل المستعمرات، إزالة الأعشاب، واستخدام صابون حشري أو مبيد من انتقائي.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (16,'Downy Mildew','مرض البياض الزغبي','An oomycete disease that develops under cool moist conditions and affects leaves and stems.','مرض شبيه بالفطريات يتطور في الجو البارد الرطب ويصيب الأوراق والسيقان.','Yellow angular leaf spots, grey or white downy growth underneath, leaf collapse, and reduced yield.','بقع صفراء زاوية، نمو زغبي رمادي أو أبيض أسفل الورقة، انهيار الأوراق، وانخفاض المحصول.','Improve ventilation, avoid overhead irrigation, remove infected leaves, rotate crops, and use labeled downy mildew fungicides.','تحسين التهوية، تجنب الري بالرش، إزالة الأوراق المصابة، اتباع دورة زراعية، واستخدام مبيدات مخصصة للبياض الزغبي.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (17,'Club Root','مرض تضخم الجذور','A soilborne disease of brassicas caused by Plasmodiophora brassicae that deforms roots.','مرض تربة يصيب العائلة الصليبية تسببه Plasmodiophora brassicae ويشوه الجذور.','Swollen club-shaped roots, wilting in heat, stunting, yellowing, and poor head formation.','تضخم الجذور بشكل صولجاني، ذبول وقت الحر، تقزم، اصفرار، وضعف تكوين الرؤوس.','Use long crop rotation, raise soil pH with lime if appropriate, improve drainage, and plant resistant varieties.','اتباع دورة زراعية طويلة، رفع pH التربة بالجير عند الحاجة، تحسين الصرف، وزراعة أصناف مقاومة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (18,'Ring Spot','مرض التبقع الحلقي','A fungal or viral leaf disease recognized by circular ring-like spots on foliage.','مرض ورقي فطري أو فيروسي يتميز ببقع دائرية حلقية على الأوراق.','Circular grey or brown spots with dark rings, yellowing, leaf drop, and reduced plant vigor.','بقع دائرية رمادية أو بنية بحلقات داكنة، اصفرار، تساقط أوراق، وضعف عام.','Remove infected leaves, avoid leaf wetness, control vectors if viral, and apply fungicides when fungal diagnosis is confirmed.','إزالة الأوراق المصابة، تقليل بلل الأوراق، مكافحة النواقل إذا كان فيروسياً، ورش مبيد فطري عند تأكيد السبب الفطري.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (19,'Cercospora Leaf Spot','مرض تبقع أوراق السيركوسبورا','A fungal disease caused by Cercospora species that creates many small leaf spots.','مرض فطري تسببه أنواع Cercospora ويظهر كبقع صغيرة عديدة على الأوراق.','Small tan or grey spots with reddish-brown margins, yellowing, leaf drying, and defoliation.','بقع صغيرة بنية فاتحة أو رمادية بحواف حمراء بنية، اصفرار، جفاف، وتساقط الأوراق.','Rotate crops, remove debris, use resistant varieties, avoid overhead watering, and apply fungicides early.','اتباع دورة زراعية، إزالة المخلفات، استخدام أصناف مقاومة، تجنب الري بالرش، والرش المبكر بمبيد فطري.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (20,'Common Rust','مرض الصدأ الشائع','A fungal rust disease producing powdery pustules mainly on leaves.','مرض صدأ فطري ينتج بثرات مسحوقية غالباً على الأوراق.','Orange to brown pustules, chlorotic spots, leaf drying, and reduced photosynthesis.','بثرات برتقالية إلى بنية، بقع صفراء، جفاف الأوراق، وانخفاض البناء الضوئي.','Plant resistant hybrids, remove volunteer plants, monitor early, and apply fungicides when rust appears before flowering.','زراعة هجن مقاومة، إزالة النباتات المتطوعة، المراقبة المبكرة، ورش مبيد فطري إذا ظهر الصدأ قبل الإزهار.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (21,'Northern Leaf Blight','مرض اللفحة الشمالية للأوراق','A fungal corn disease caused by Exserohilum turcicum, favored by humid weather.','مرض فطري في الذرة تسببه Exserohilum turcicum وينتشر مع الرطوبة.','Long cigar-shaped grey-green to tan lesions, leaf blight, and yield loss.','بقع طويلة تشبه السيجار لونها رمادي أخضر إلى بني فاتح، لفحة أوراق، ونقص في الإنتاج.','Use resistant hybrids, bury or remove residue, rotate crops, and apply fungicides on susceptible crops at early lesion development.','استخدام هجن مقاومة، دفن أو إزالة البقايا، تدوير المحصول، ورش مبيد فطري عند بداية ظهور البقع.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (22,'Powdery Mildew','مرض البياض الدقيقي','A fungal disease that grows as white powdery colonies on plant surfaces.','مرض فطري يظهر كنمو أبيض دقيقي على سطح النبات.','White powdery patches, leaf curling, yellowing, reduced growth, and premature leaf drop.','بقع بيضاء دقيقية، التفاف الأوراق، اصفرار، ضعف النمو، وتساقط مبكر.','Improve air circulation, avoid excess nitrogen, remove infected leaves, and use sulfur or labeled fungicides.','تحسين التهوية، تجنب زيادة النيتروجين، إزالة الأوراق المصابة، واستخدام الكبريت أو مبيدات فطرية مسجلة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (23,'Insect Pest Disease','مرض الآفات الحشرية','Plant injury caused by insect pests feeding on leaves, stems, roots, or fruit.','ضرر نباتي ناتج عن حشرات تتغذى على الأوراق أو السيقان أو الجذور أو الثمار.','Chewed leaves, sap-sucking marks, wilting, holes, frass, distorted growth, or visible insects.','أوراق مقروضة، آثار امتصاص، ذبول، ثقوب، فضلات حشرية، نمو مشوه، أو ظهور الحشرات.','Identify the pest, monitor thresholds, remove heavily infested parts, use biological control, and apply suitable pesticides responsibly.','تحديد نوع الآفة، مراقبة حد الضرر، إزالة الأجزاء الشديدة الإصابة، استخدام المكافحة الحيوية، والرش المسؤول بمبيد مناسب.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (24,'Leaf Spot Disease','مرض تبقع الأوراق','A general disease causing localized spots on leaves from fungal, bacterial, or environmental causes.','مرض عام يسبب بقعاً محددة على الأوراق نتيجة فطريات أو بكتيريا أو عوامل بيئية.','Brown, black, or yellow spots, halos, tissue death, leaf yellowing, and defoliation.','بقع بنية أو سوداء أو صفراء، هالات، موت نسيج، اصفرار وتساقط الأوراق.','Remove infected foliage, reduce humidity, water at soil level, improve spacing, and treat based on confirmed cause.','إزالة الأوراق المصابة، تقليل الرطوبة، الري عند مستوى التربة، تحسين المسافات، والمعالجة حسب السبب المؤكد.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (25,'Mosaic Virus Disease','مرض فيروس الموزاييك','A viral disease that disrupts leaf color and growth in many crops.','مرض فيروسي يسبب تداخل ألوان الأوراق واضطراب النمو في محاصيل كثيرة.','Mottled light and dark green leaves, distortion, stunting, reduced flowering, and poor yield.','تبرقش أخضر فاتح وداكن، تشوه الأوراق، تقزم، قلة الإزهار، وضعف الإنتاج.','Remove infected plants, control aphids or other vectors, disinfect tools, and use certified virus-free seed or transplants.','إزالة النباتات المصابة، مكافحة المن أو النواقل، تعقيم الأدوات، واستخدام بذور أو شتلات معتمدة خالية من الفيروس.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (26,'Small Leaf Disease','مرض صغر الأوراق','A disorder or disease complex causing abnormally small leaves due to pathogens, nutrient issues, or vectors.','مرض أو اضطراب مركب يسبب صغر حجم الأوراق بسبب مسببات مرضية أو نقص غذائي أو نواقل.','Small narrow leaves, shortened internodes, yellowing, stunting, and poor fruiting.','أوراق صغيرة وضيقة، قصر السلاميات، اصفرار، تقزم، وضعف الإثمار.','Test soil and tissue nutrients, control insect vectors, remove infected plants, and improve balanced fertilization.','فحص التربة والأنسجة غذائياً، مكافحة النواقل الحشرية، إزالة النباتات المصابة، وتحسين التسميد المتوازن.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (27,'White Mold Disease','مرض العفن الأبيض','A fungal disease caused by Sclerotinia species that produces white cottony growth and hard sclerotia.','مرض فطري تسببه أنواع Sclerotinia ويظهر كنمو قطني أبيض وأجسام حجرية سوداء.','Water-soaked lesions, white fluffy mold, stem rot, wilting, and black sclerotia inside stems.','بقع مائية، عفن أبيض قطني، تعفن الساق، ذبول، وأجسام حجرية سوداء داخل الساق.','Rotate with non-hosts, reduce canopy humidity, avoid excess nitrogen, remove infected plants, and use labeled fungicides at flowering.','التدوير بمحاصيل غير عائلة، تقليل رطوبة المجموع الخضري، تجنب زيادة النيتروجين، إزالة المصاب، والرش وقت الإزهار بمبيد مسجل.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (28,'Wilt Disease','مرض الذبول','A disease complex where vascular infection or root damage blocks water movement in the plant.','مرض مركب يحدث عند انسداد الأوعية أو تلف الجذور مما يمنع انتقال الماء.','Sudden or gradual wilting, yellowing, vascular browning, stunting, and plant death.','ذبول مفاجئ أو تدريجي، اصفرار، تلون بني بالأوعية، تقزم، وموت النبات.','Use resistant varieties, rotate crops, improve drainage, avoid root injury, and remove infected plants.','زراعة أصناف مقاومة، اتباع دورة زراعية، تحسين الصرف، تجنب جرح الجذور، وإزالة النباتات المصابة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (29,'Esca (Black Measles)','مرض الإيسكا (الحصبة السوداء)','A grapevine trunk disease complex caused by wood-inhabiting fungi that degrade vascular tissue.','مرض معقد في جذع العنب تسببه فطريات تعيش في الخشب وتضعف الأنسجة الوعائية.','Tiger-stripe leaf patterns, berry black spots, dieback, reduced vigor, and sudden vine collapse.','نقوش مخططة على الأوراق، بقع سوداء على الحبات، موت أفرع، ضعف نمو، وانهيار مفاجئ للكرمة.','Prune during dry weather, protect pruning wounds, remove dead wood, avoid vine stress, and replace severely affected vines.','التقليم في الجو الجاف، حماية جروح التقليم، إزالة الخشب الميت، تقليل الإجهاد، واستبدال الكرمات الشديدة الإصابة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (30,'Leaf Blight (Isariopsis Leaf Spot)','مرض لفحة الأوراق (تبقع إيزاريوپسس)','A grape leaf disease caused by Pseudocercospora vitis, producing angular brown lesions.','مرض يصيب أوراق العنب تسببه Pseudocercospora vitis ويشكل بقعاً بنية زاوية.','Brown angular spots, dark fungal growth on undersides, yellowing, leaf drying, and defoliation.','بقع بنية زاوية، نمو فطري داكن أسفل الورقة، اصفرار، جفاف، وتساقط الأوراق.','Remove infected leaves, prune for air flow, reduce humidity, and apply recommended grape fungicides.','إزالة الأوراق المصابة، التقليم للتهوية، تقليل الرطوبة، واستخدام مبيدات فطرية موصى بها للعنب.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (31,'Canker','مرض التقرح','A localized dead area on bark or stems caused by fungi, bacteria, or injury.','منطقة ميتة موضعية على القلف أو الساق سببها فطريات أو بكتيريا أو جروح.','Sunken bark lesions, cracking, gum or sap ooze, branch dieback, and weak growth.','تقرحات غائرة في القلف، تشقق، خروج صمغ أو عصارة، موت أفرع، وضعف النمو.','Prune below the canker, disinfect tools, avoid injuries, improve tree vigor, and apply protectants where recommended.','التقليم أسفل التقرح، تعقيم الأدوات، تجنب الجروح، تحسين قوة النبات، واستخدام مواد وقائية عند التوصية.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (32,'Dot','مرض التبقع النقطي','A minor spotted disease or blemish characterized by small dark dots on leaves or fruit.','مرض أو عيب بقعي بسيط يتميز بنقاط داكنة صغيرة على الأوراق أو الثمار.','Tiny black or brown dots, slight yellowing, superficial blemishes, and reduced market quality.','نقاط سوداء أو بنية صغيرة، اصفرار خفيف، عيوب سطحية، وانخفاض الجودة التسويقية.','Improve sanitation, remove infected debris, avoid prolonged wetness, and apply preventive fungicides if the spots spread.','تحسين النظافة الزراعية، إزالة المخلفات المصابة، تجنب البلل الطويل، واستخدام مبيد وقائي إذا انتشرت النقاط.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (33,'Mummification','مرض تحنط الثمار','A fruit disease condition where infected fruit dries, shrivels, and remains attached or falls as a mummy.','حالة مرضية في الثمار حيث تجف الثمرة المصابة وتنكمش وتبقى معلقة أو تسقط كثمرة محنطة.','Shriveled dry fruit, brown rot, fungal spores, fruit drop, and carryover infection for next season.','ثمار جافة منكمشة، تعفن بني، أبواغ فطرية، تساقط ثمار، وبقاء مصدر عدوى للموسم التالي.','Collect and destroy mummified fruit, prune infected twigs, improve air flow, and spray fungicides during bloom and fruit development.','جمع وإتلاف الثمار المحنطة، تقليم الأفرع المصابة، تحسين التهوية، والرش أثناء الإزهار ونمو الثمار.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (34,'Rust','مرض الصدأ','A fungal disease producing rusty orange, yellow, or brown pustules on leaves and stems.','مرض فطري يسبب بثرات صدئية برتقالية أو صفراء أو بنية على الأوراق والسيقان.','Powdery rust pustules, yellow leaf spots, premature leaf drop, and reduced vigor.','بثرات صدئية مسحوقية، بقع صفراء، تساقط مبكر للأوراق، وضعف عام.','Plant resistant varieties, remove alternate hosts where relevant, avoid overhead irrigation, and apply rust fungicides early.','زراعة أصناف مقاومة، إزالة العوائل البديلة عند الحاجة، تجنب الري بالرش، والرش المبكر بمبيدات الصدأ.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (35,'Bacterial Blight','مرض اللفحة البكتيرية','A bacterial disease that kills leaf and stem tissue, often spreading by rain splash and tools.','مرض بكتيري يميت أنسجة الأوراق والسيقان وينتشر غالباً برذاذ المطر والأدوات.','Water-soaked angular spots, brown blighting, yellow halos, stem lesions, and wilting shoots.','بقع زاوية مائية، لفحة بنية، هالات صفراء، إصابات على الساق، وذبول نموات.','Use clean seed, avoid overhead irrigation, sanitize tools, remove infected plants, and apply copper products preventively.','استخدام بذور سليمة، تجنب الري بالرش، تعقيم الأدوات، إزالة المصاب، واستخدام مركبات النحاس وقائياً.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (36,'Citrus Canker','مرض تقرح الحمضيات','A highly contagious bacterial citrus disease caused by Xanthomonas citri.','مرض بكتيري شديد العدوى يصيب الحمضيات وتسببه Xanthomonas citri.','Raised corky lesions with yellow halos on leaves, fruit, and twigs, defoliation, and fruit drop.','بقع فلينية مرتفعة بهالات صفراء على الأوراق والثمار والأفرع، تساقط أوراق وثمار.','Plant disease-free stock, remove infected shoots, disinfect tools, control wind-driven spread, and apply copper sprays.','زراعة شتلات سليمة، إزالة الأفرع المصابة، تعقيم الأدوات، تقليل الانتشار بالرياح، ورش النحاس.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (37,'Curl Virus','مرض تجعد الفيروس','A viral disease causing leaf curling and plant stunting, commonly spread by whiteflies or aphids.','مرض فيروسي يسبب التفاف الأوراق وتقزم النبات وينتقل غالباً بالذبابة البيضاء أو المن.','Upward or downward leaf curling, yellowing, thickened leaves, stunting, and poor fruit set.','التفاف الأوراق للأعلى أو الأسفل، اصفرار، سماكة الأوراق، تقزم، وضعف عقد الثمار.','Remove infected plants, control vectors, use insect-proof nets, plant resistant varieties, and eliminate weed hosts.','إزالة النباتات المصابة، مكافحة النواقل، استخدام الشباك الحشرية، زراعة أصناف مقاومة، وإزالة الأعشاب العائلة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (38,'Deficiency Leaf','مرض نقص العناصر في الأوراق','A nutritional disorder where leaves show abnormal color or shape due to lack of essential nutrients.','اضطراب غذائي تظهر فيه الأوراق بلون أو شكل غير طبيعي بسبب نقص العناصر الأساسية.','Chlorosis, interveinal yellowing, marginal burn, small leaves, weak growth, and poor yield.','اصفرار، اصفرار بين العروق، احتراق الحواف، صغر الأوراق، ضعف النمو، وقلة الإنتاج.','Test soil and leaves, correct pH, apply the deficient nutrient, improve irrigation, and avoid over-fertilization imbalance.','تحليل التربة والأوراق، تعديل pH، إضافة العنصر الناقص، تحسين الري، وتجنب اختلال التسميد.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (39,'Dry Leaf','مرض جفاف الأوراق','A physiological or disease-related condition where leaves dry due to stress, infection, or root problems.','حالة فسيولوجية أو مرضية تجف فيها الأوراق بسبب الإجهاد أو العدوى أو مشاكل الجذور.','Leaf tip burn, brittle dry leaves, browning margins, wilting, and reduced growth.','احتراق أطراف الأوراق، أوراق جافة هشة، اسمرار الحواف، ذبول، وضعف النمو.','Check irrigation and drainage, reduce heat or salt stress, remove diseased leaves, and treat root or foliar pathogens if confirmed.','فحص الري والصرف، تقليل إجهاد الحرارة أو الملوحة، إزالة الأوراق المصابة، ومعالجة أمراض الجذور أو الأوراق عند تأكيدها.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (40,'Sooty Mould','مرض العفن السخامي','A black fungal growth that develops on honeydew secreted by sap-sucking insects.','نمو فطري أسود يتكون على الإفرازات العسلية التي تفرزها الحشرات الماصة.','Black coating on leaves or fruit, sticky surfaces, reduced photosynthesis, and presence of aphids, scales, or whiteflies.','طبقة سوداء على الأوراق أو الثمار، سطح لزج، انخفاض البناء الضوئي، ووجود من أو حشرات قشرية أو ذباب أبيض.','Control honeydew-producing insects, wash foliage, prune dense canopies, and avoid unnecessary fungicide because the main cause is insects.','مكافحة الحشرات المفرزة للعسل، غسل الأوراق، تقليم الكثافة، وتجنب المبيد الفطري غير الضروري لأن السبب الأساسي حشري.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (41,'Spider Mites','مرض العناكب الحمراء','Tiny mite pests that feed on leaf cells and multiply quickly in hot dry conditions.','آفات حلمية صغيرة تتغذى على خلايا الورقة وتتكاثر بسرعة في الجو الحار الجاف.','Fine stippling, bronzed leaves, webbing, leaf drop, and tiny mites on leaf undersides.','تنقيط دقيق، تلون برونزي، خيوط عنكبوتية، تساقط أوراق، ووجود الحلم أسفل الورقة.','Spray water to reduce dust, conserve predatory mites, avoid excess broad-spectrum insecticides, and use miticides when needed.','رش الماء لتقليل الغبار، حماية الأكاروسات المفترسة، تجنب المبيدات الواسعة الزائدة، واستخدام مبيد أكاروسي عند الحاجة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (42,'Bacterial','مرض العدوى البكتيرية','A general bacterial plant disease causing spots, wilts, rots, or blights depending on the pathogen.','مرض بكتيري عام يسبب بقعاً أو ذبولاً أو تعفناً أو لفحات حسب نوع المسبب.','Water-soaked lesions, yellow halos, ooze, wilting, soft rot, and rapid spread in wet weather.','بقع مائية، هالات صفراء، إفرازات، ذبول، تعفن طري، وانتشار سريع مع الرطوبة.','Use clean planting material, sanitize tools, avoid wet handling, improve drainage, and apply copper or approved bactericides preventively.','استخدام مواد زراعة سليمة، تعقيم الأدوات، تجنب العمل عند البلل، تحسين الصرف، واستخدام النحاس أو مبيدات بكتيرية معتمدة وقائياً.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (43,'Downy Mildew on Lettuce','مرض البياض الزغبي في الخس','An oomycete disease of lettuce caused mainly by Bremia lactucae.','مرض بياض زغبي في الخس تسببه غالباً Bremia lactucae.','Pale yellow angular spots on upper leaves, white downy growth underneath, leaf browning, and poor quality.','بقع صفراء باهتة زاوية أعلى الورقة، نمو زغبي أبيض أسفلها، اسمرار الورقة، وضعف الجودة.','Use resistant lettuce varieties, reduce humidity, space plants well, avoid overhead irrigation, and apply labeled fungicides.','زراعة أصناف خس مقاومة، تقليل الرطوبة، ترك مسافات مناسبة، تجنب الري بالرش، واستخدام مبيدات مسجلة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (44,'Powdery Mildew on Lettuce','مرض البياض الدقيقي في الخس','A fungal lettuce disease producing white powdery growth, especially in warm dry days with humid nights.','مرض فطري في الخس يظهر كنمو أبيض دقيقي خاصة مع النهار الدافئ والليل الرطب.','White powder on leaves, yellowing, leaf distortion, reduced head quality, and early senescence.','مسحوق أبيض على الأوراق، اصفرار، تشوه، انخفاض جودة الرأس، وشيخوخة مبكرة.','Improve ventilation, avoid dense planting, remove infected leaves, and apply sulfur or labeled fungicides suitable for lettuce.','تحسين التهوية، تجنب الزراعة الكثيفة، إزالة الأوراق المصابة، واستخدام الكبريت أو مبيدات مناسبة للخس.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (45,'Septoria Blight on Lettuce','مرض لفحة السيبتوريا في الخس','A fungal lettuce disease caused by Septoria species that damages older leaves first.','مرض فطري في الخس تسببه أنواع Septoria ويبدأ غالباً بالأوراق القديمة.','Small water-soaked spots becoming brown with grey centers, many leaf lesions, blight, and leaf loss.','بقع مائية صغيرة تتحول لبنية بمراكز رمادية، كثرة البقع، لفحة، وفقدان أوراق.','Use clean seed, rotate crops, remove plant debris, water at soil level, and apply protective fungicides.','استخدام بذور سليمة، تدوير المحصول، إزالة المخلفات، الري عند التربة، ورش مبيد وقائي.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (46,'Shepherd Purse Weeds','مرض عشبة كيس الراعي','A common weed that competes with crops and can host insects and diseases, especially in brassica systems.','عشب شائع ينافس المحاصيل وقد يكون عائلاً للحشرات والأمراض خاصة مع الصليبيات.','Rosette leaves, small white flowers, heart-shaped seed pods, crop competition, and pest sheltering.','أوراق وردية، أزهار بيضاء صغيرة، قرون بذور قلبية الشكل، منافسة للمحصول، وإيواء آفات.','Remove before flowering, cultivate shallowly, mulch, rotate crops, and use approved herbicides when necessary.','إزالته قبل الإزهار، العزيق السطحي، استخدام الملش، تدوير المحصول، واستخدام مبيدات أعشاب معتمدة عند الضرورة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (47,'Viral','مرض العدوى الفيروسية','A general viral plant disease category that alters growth and color and is often spread by insects or infected seed.','تصنيف عام للأمراض الفيروسية التي تغير النمو واللون وتنتقل غالباً بالحشرات أو البذور المصابة.','Mosaic, mottling, curling, stunting, ring spots, poor flowering, and reduced yield.','تبرقش، تلطخ لوني، التفاف، تقزم، بقع حلقية، ضعف إزهار، ونقص محصول.','Remove infected plants, control vectors, use resistant varieties, disinfect tools, and plant certified disease-free material.','إزالة النباتات المصابة، مكافحة النواقل، استخدام أصناف مقاومة، تعقيم الأدوات، وزراعة مواد معتمدة خالية من المرض.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (48,'Cutting Weevil','مرض سوسة القطع','Damage caused by weevils cutting or feeding on young shoots, leaves, or stems.','ضرر تسببه سوسة تقطع أو تتغذى على البادرات أو الأوراق أو السيقان.','Cut seedlings, notched leaves, wilting shoots, feeding holes, and larvae near crowns or roots.','بادرات مقطوعة، حواف أوراق مقروضة، ذبول نموات، ثقوب تغذية، ويرقات قرب التاج أو الجذور.','Remove crop debris, cultivate soil, use traps, protect seedlings, and apply registered insecticides at early infestation.','إزالة بقايا المحصول، حراثة التربة، استخدام المصائد، حماية الشتلات، والرش بمبيد مسجل عند بداية الإصابة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (49,'Die Back','مرض موت الأفرع الخلفي','A condition where shoots or branches die from the tip backward due to pathogens, stress, or cankers.','حالة تموت فيها الأفرع من الأطراف إلى الخلف بسبب مسببات مرضية أو إجهاد أو تقرحات.','Dead shoot tips, leaf drying, bark discoloration, cankers, reduced vigor, and branch decline.','موت أطراف الأفرع، جفاف الأوراق، تغير لون القلف، تقرحات، ضعف نمو، وتدهور الأفرع.','Prune into healthy wood, disinfect tools, reduce stress, improve nutrition and irrigation, and treat confirmed pathogens.','التقليم حتى الخشب السليم، تعقيم الأدوات، تقليل الإجهاد، تحسين التغذية والري، ومعالجة المسبب المؤكد.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (50,'Gall Midge','مرض ذبابة المرارة','A tiny fly whose larvae cause swellings, galls, or distorted plant tissues.','ذبابة صغيرة تسبب يرقاتها انتفاخات أو أوراماً أو تشوهات في أنسجة النبات.','Galls on leaves or shoots, curled tissues, stunted growing points, discoloration, and tiny larvae inside galls.','أورام على الأوراق أو النموات، التفاف الأنسجة، تقزم القمم، تغير لون، ويرقات صغيرة داخل الأورام.','Remove galled tissues, destroy infested debris, monitor adult flights, use resistant varieties, and apply insecticides at egg hatch if needed.','إزالة الأنسجة المتورمة، إتلاف المخلفات المصابة، مراقبة طيران الحشرات، استخدام أصناف مقاومة، والرش وقت فقس البيض عند الحاجة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (51,'Aculus olearius','مرض أكيولوس أولياريوس','An eriophyid mite pest of olive that feeds on leaves and young fruit.','حلم دودي من آفات الزيتون يتغذى على الأوراق والثمار الحديثة.','Leaf bronzing, curling, rough fruit skin, reduced fruit size, and tiny mites visible under magnification.','تلون برونزي للأوراق، التفاف، خشونة قشرة الثمار، صغر حجم الثمرة، وحلم صغير يرى بالتكبير.','Monitor new growth, avoid unnecessary insecticides, conserve predators, and apply suitable miticides or sulfur when populations are high.','مراقبة النموات الحديثة، تجنب المبيدات غير الضرورية، حماية المفترسات، واستخدام مبيد أكاروسي أو كبريت عند زيادة الإصابة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (52,'Peacock Spot','مرض تبقع عين الطاووس','An olive fungal leaf disease caused by Venturia oleaginea, favored by cool wet weather.','مرض فطري يصيب أوراق الزيتون تسببه Venturia oleaginea وينتشر في الجو البارد الرطب.','Circular dark spots with yellow halos resembling peacock eyes, leaf yellowing, and defoliation.','بقع دائرية داكنة بهالات صفراء تشبه عين الطاووس، اصفرار وتساقط الأوراق.','Prune for air circulation, avoid excessive nitrogen, remove infected leaves, and apply copper sprays before rainy seasons.','التقليم للتهوية، تجنب زيادة النيتروجين، إزالة الأوراق المصابة، ورش النحاس قبل مواسم المطر.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (53,'Citrus Canker Diseases Leaf','مرض تقرح أوراق الحمضيات','Leaf infection phase of citrus canker caused by Xanthomonas citri.','الطور الورقي من مرض تقرح الحمضيات البكتيري الذي تسببه Xanthomonas citri.','Raised corky leaf lesions, oily margins, yellow halos, leaf distortion, and premature leaf fall.','تقرحات فلينية مرتفعة على الأوراق، حواف زيتية، هالات صفراء، تشوه، وتساقط مبكر.','Use clean nursery trees, prune infected flushes, disinfect tools, manage leafminer damage, and apply copper protectants.','استخدام شتلات سليمة، تقليم النموات المصابة، تعقيم الأدوات، مكافحة حفار أوراق الحمضيات، ورش النحاس الوقائي.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (54,'Citrus Nutrient Deficiency Yellow','مرض اصفرار نقص عناصر الحمضيات','A citrus nutritional disorder causing yellow leaves due to deficiencies such as nitrogen, iron, zinc, or magnesium.','اضطراب غذائي في الحمضيات يسبب اصفرار الأوراق بسبب نقص مثل النيتروجين أو الحديد أو الزنك أو المغنيسيوم.','General yellowing, interveinal chlorosis, small leaves, twig dieback, and poor fruit size depending on nutrient.','اصفرار عام أو بين العروق، صغر الأوراق، موت أطراف، وضعف حجم الثمار حسب العنصر الناقص.','Run soil and leaf tests, correct pH, apply balanced citrus fertilizer and specific micronutrients, and improve irrigation.','إجراء تحليل تربة وأوراق، تعديل pH، إضافة تسميد متوازن للحمضيات وعناصر صغرى محددة، وتحسين الري.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (55,'Multiple Diseases Leaf','مرض الإصابات المتعددة في الأوراق','A mixed leaf condition where more than one pathogen or stress affects the same plant.','حالة ورقية مختلطة عندما يصيب النبات أكثر من مسبب مرضي أو عامل إجهاد.','Mixed spots, blight, yellowing, necrosis, distortion, and symptoms that vary across leaves.','بقع مختلفة، لفحة، اصفرار، موت أنسجة، تشوه، وأعراض متباينة بين الأوراق.','Diagnose the main cause, remove heavily infected leaves, improve cultural conditions, and combine targeted fungicide, bactericide, or pest control as needed.','تشخيص السبب الأساسي، إزالة الأوراق شديدة الإصابة، تحسين ظروف الزراعة، والجمع بين مبيد فطري أو بكتيري أو مكافحة آفات حسب الحاجة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (56,'Leafminer Leaf','مرض حفّار أنفاق الأوراق','Damage caused by leafminer larvae tunneling between leaf surfaces.','ضرر تسببه يرقات حفار الأوراق التي تحفر أنفاقاً بين سطحي الورقة.','Winding white or brown tunnels, distorted young leaves, reduced photosynthesis, and secondary infection entry points.','أنفاق متعرجة بيضاء أو بنية، تشوه الأوراق الحديثة، انخفاض البناء الضوئي، ومداخل لعدوى ثانوية.','Remove mined leaves, use yellow sticky traps, protect natural parasitoids, and apply selective insecticides on young larvae.','إزالة الأوراق المحفورة، استخدام المصائد الصفراء، حماية الطفيليات النافعة، والرش بمبيد انتقائي على اليرقات الصغيرة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (57,'Bacterial Spot','مرض التبقع البكتيري','A bacterial disease producing spots on leaves, stems, and fruit in crops such as tomato and pepper.','مرض بكتيري يسبب بقعاً على الأوراق والسيقان والثمار مثل الطماطم والفلفل.','Small water-soaked spots, yellow halos, dark scabby fruit lesions, leaf drop, and blight.','بقع صغيرة مائية، هالات صفراء، بقع جرباء داكنة على الثمار، تساقط أوراق، ولفحة.','Use pathogen-free seed, rotate crops, avoid overhead irrigation, remove debris, and use copper plus labeled protectants preventively.','استخدام بذور خالية من المرض، تدوير المحاصيل، تجنب الري بالرش، إزالة المخلفات، واستخدام النحاس مع مواد وقائية مسجلة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (58,'Alternaria','مرض الألترناريا','A fungal disease group caused by Alternaria species affecting leaves, stems, and fruit.','مجموعة أمراض فطرية تسببها أنواع Alternaria وتصيب الأوراق والسيقان والثمار.','Dark spots with concentric rings, yellowing, blight, stem cankers, and fruit rot.','بقع داكنة بحلقات متداخلة، اصفرار، لفحة، تقرحات ساق، وتعفن ثمار.','Rotate crops, reduce leaf wetness, remove infected residue, use resistant varieties, and apply fungicides when needed.','تدوير المحاصيل، تقليل بلل الأوراق، إزالة البقايا المصابة، استخدام أصناف مقاومة، والرش عند الحاجة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (59,'Cercospora','مرض السيركوسبورا','A fungal disease group causing leaf spots in many vegetables, fruits, and field crops.','مجموعة أمراض فطرية تسبب بقعاً ورقية في خضار وفاكهة ومحاصيل حقلية كثيرة.','Numerous small grey or tan spots with dark borders, yellowing, leaf thinning, and defoliation.','بقع صغيرة كثيرة رمادية أو بنية فاتحة بحواف داكنة، اصفرار، ضعف الورقة، وتساقطها.','Practice rotation, destroy infected debris, avoid overhead watering, use resistant cultivars, and apply fungicides early.','اتباع دورة زراعية، التخلص من المخلفات المصابة، تجنب الري بالرش، استخدام أصناف مقاومة، والرش المبكر.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (60,'Early Blight','مرض اللفحة المبكرة','A common Alternaria disease of tomato and potato that starts on older foliage.','مرض Alternaria شائع في الطماطم والبطاطس يبدأ غالباً على الأوراق السفلية القديمة.','Target-like brown leaf spots, yellowing, lower leaf drop, collar rot on seedlings, and fruit lesions.','بقع بنية تشبه الهدف، اصفرار، تساقط الأوراق السفلية، تعفن طوق الشتلات، وبقع على الثمار.','Remove lower infected leaves, mulch, stake plants, rotate away from solanaceous crops, and use fungicide programs.','إزالة الأوراق السفلية المصابة، استخدام الملش، تدعيم النباتات، تدوير بعيداً عن العائلة الباذنجانية، واتباع برنامج رش فطري.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (61,'Late Blight','مرض اللفحة المتأخرة','A destructive oomycete disease caused by Phytophthora infestans in potato and tomato.','مرض مدمر شبيه بالفطريات تسببه Phytophthora infestans في البطاطس والطماطم.','Water-soaked leaf lesions, white mold at lesion edges, brown stem lesions, rapid collapse, and fruit rot.','بقع مائية على الأوراق، نمو أبيض عند حواف البقع، بقع بنية على الساق، انهيار سريع، وتعفن ثمار.','Plant certified seed, destroy volunteers, improve air flow, avoid wet foliage, and apply late-blight fungicides preventively.','زراعة تقاوي معتمدة، إزالة النباتات المتطوعة، تحسين التهوية، تجنب بلل الأوراق، واستخدام مبيدات اللفحة المتأخرة وقائياً.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (62,'Bacterial Leaf Spot','مرض التبقع البكتيري للأوراق','A bacterial leaf disease causing angular or irregular spots that expand under wet conditions.','مرض بقع بكتيري يسبب بقعاً زاوية أو غير منتظمة تتوسع في الجو الرطب.','Water-soaked angular spots, yellow halos, necrotic patches, leaf tearing, and defoliation.','بقع زاوية مائية، هالات صفراء، مناطق ميتة، تمزق الورقة، وتساقطها.','Use clean seed and transplants, avoid overhead irrigation, sanitize tools, rotate crops, and apply copper products preventively.','استخدام بذور وشتلات سليمة، تجنب الري بالرش، تعقيم الأدوات، تدوير المحصول، ورش النحاس وقائياً.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (63,'Mosaic Disease','مرض الموزاييك','A viral disease causing patchy leaf discoloration and distorted plant growth.','مرض فيروسي يسبب تبرقشاً لونياً وتشوه نمو النبات.','Mosaic mottling, curled or distorted leaves, stunting, poor fruit quality, and reduced yield.','تبرقش موزايكي، أوراق ملتفة أو مشوهة، تقزم، ضعف جودة الثمار، ونقص المحصول.','Remove infected plants, control insect vectors, disinfect tools, avoid tobacco contamination in solanaceous crops, and use resistant varieties.','إزالة النباتات المصابة، مكافحة النواقل، تعقيم الأدوات، تجنب تلوث التبغ في الباذنجانيات، واستخدام أصناف مقاومة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (64,'Black Leaf Spot','مرض التبقع الأسود للأوراق','A leaf spot disease causing dark necrotic spots from fungi or bacteria.','مرض بقع ورقية يسبب بقعاً سوداء ميتة بسبب فطريات أو بكتيريا.','Black circular or irregular spots, yellowing around lesions, leaf blight, and premature leaf fall.','بقع سوداء دائرية أو غير منتظمة، اصفرار حولها، لفحة، وتساقط مبكر.','Remove infected leaves, avoid splashing water, improve spacing, and use fungicide or bactericide after diagnosis.','إزالة الأوراق المصابة، تجنب رذاذ الماء، تحسين المسافات، واستخدام مبيد فطري أو بكتيري بعد التشخيص.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (65,'Flea Beetle','مرض خنفساء البرغوث','Small jumping beetles that chew many tiny holes in leaves, especially seedlings.','خنافس صغيرة قافزة تقرض ثقوباً كثيرة صغيرة في الأوراق خاصة البادرات.','Shot-hole leaf feeding, small pits, weakened seedlings, stunting, and beetles jumping when disturbed.','ثقوب صغيرة كالرصاص، حفر سطحية، ضعف البادرات، تقزم، وقفز الخنافس عند الإزعاج.','Use row covers, remove weeds, rotate crops, trap crops where useful, and apply insecticides when seedlings are at risk.','استخدام أغطية الصفوف، إزالة الأعشاب، تدوير المحصول، استخدام محاصيل جاذبة عند الفائدة، والرش عند تهديد البادرات.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (66,'Southern Blight','مرض اللفحة الجنوبية','A soilborne fungal disease caused by Sclerotium rolfsii that attacks stems near soil level.','مرض فطري ينتقل بالتربة تسببه Sclerotium rolfsii ويصيب الساق قرب سطح التربة.','Wilting, stem rot at soil line, white fan-like mycelium, and small tan sclerotia.','ذبول، تعفن الساق عند سطح التربة، نمو فطري أبيض مروحي، وأجسام حجرية بنية صغيرة.','Remove infected plants with surrounding soil, rotate crops, improve drainage, avoid deep planting, and use soil treatments where approved.','إزالة النباتات المصابة مع التربة حولها، تدوير المحاصيل، تحسين الصرف، تجنب الزراعة العميقة، واستخدام معاملات تربة معتمدة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (67,'Sudden Death Syndrome','مرض متلازمة الموت المفاجئ','A soybean disease complex associated with Fusarium root infection and toxin movement to leaves.','مرض معقد في فول الصويا يرتبط بإصابة الجذور بفطر Fusarium وانتقال السموم للأوراق.','Interveinal chlorosis and necrosis, green veins, root rot, leaf drop, and sudden plant decline.','اصفرار وموت بين العروق مع بقاء العروق خضراء، تعفن جذور، تساقط أوراق، وتدهور مفاجئ.','Plant resistant varieties, improve drainage, reduce soil compaction, use seed treatments, and rotate with non-host crops.','زراعة أصناف مقاومة، تحسين الصرف، تقليل انضغاط التربة، استخدام معاملات البذور، والتدوير بمحاصيل غير عائلة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (68,'Yellow Mosaic','مرض الموزاييك الأصفر','A viral disease producing bright yellow mosaic patterns, often spread by whiteflies or aphids.','مرض فيروسي يسبب تبرقشاً أصفر واضحاً وينتقل غالباً بالذبابة البيضاء أو المن.','Yellow mosaic patches, leaf curling, stunting, fewer pods or fruit, and reduced yield.','بقع موزاييك صفراء، التفاف أوراق، تقزم، قلة القرون أو الثمار، ونقص المحصول.','Remove infected plants early, control vectors, use resistant varieties, remove weed hosts, and plant healthy seed.','إزالة النباتات المصابة مبكراً، مكافحة النواقل، استخدام أصناف مقاومة، إزالة الأعشاب العائلة، وزراعة بذور سليمة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (69,'Brown Spot','مرض التبقع البني','A fungal disease causing brown lesions on leaves and sometimes stems or pods.','مرض فطري يسبب بقعاً بنية على الأوراق وأحياناً السيقان أو القرون.','Small to large brown spots, yellowing, lower leaf defoliation, and reduced vigor.','بقع بنية صغيرة إلى كبيرة، اصفرار، تساقط الأوراق السفلية، وضعف النمو.','Rotate crops, bury residue, avoid overhead irrigation, plant resistant varieties, and apply fungicides if disease develops early.','تدوير المحاصيل، دفن المخلفات، تجنب الري بالرش، زراعة أصناف مقاومة، والرش إذا ظهر المرض مبكراً.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (70,'Crestamento','مرض كريستامنتو','A blight or scorch-like disease name used for leaf burning symptoms in some crops.','اسم يستخدم لأعراض لفحة أو احتراق أوراق في بعض المحاصيل.','Leaf edge burn, brown blighted areas, yellowing, drying leaves, and reduced photosynthetic area.','احتراق حواف الأوراق، مناطق بنية ملفوحة، اصفرار، جفاف الأوراق، ونقص مساحة البناء الضوئي.','Identify whether the cause is fungal, bacterial, or stress; improve irrigation, remove infected leaves, and apply targeted treatments.','تحديد هل السبب فطري أو بكتيري أو إجهاد؛ تحسين الري، إزالة الأوراق المصابة، واستخدام علاج موجه.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (71,'Ferrugen','مرض فيروجين','A rust-like disease condition producing reddish-brown spots or pustules on foliage.','حالة مرضية تشبه الصدأ وتسبب بقعاً أو بثرات بنية محمرة على الأوراق.','Reddish-brown lesions, rusty powder, yellow halos, leaf drying, and premature defoliation.','بقع بنية محمرة، مسحوق صدئي، هالات صفراء، جفاف، وتساقط مبكر.','Remove infected leaves, reduce humidity, use resistant varieties when available, and apply rust-control fungicides early.','إزالة الأوراق المصابة، تقليل الرطوبة، استخدام أصناف مقاومة عند توفرها، والرش المبكر بمبيدات الصدأ.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (72,'Septoria','مرض السيبتوريا','A fungal disease group causing small spots with pale centers and dark fruiting bodies.','مجموعة أمراض فطرية تسبب بقعاً صغيرة بمراكز فاتحة وأجسام ثمرية داكنة.','Small circular spots, grey centers, dark specks, yellowing leaves, and defoliation.','بقع دائرية صغيرة، مراكز رمادية، نقاط داكنة، اصفرار، وتساقط الأوراق.','Rotate crops, remove infected debris, stake plants, avoid wet foliage, and apply protective fungicides.','تدوير المحاصيل، إزالة المخلفات المصابة، تدعيم النباتات، تجنب بلل الأوراق، ورش مبيدات وقائية.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (73,'Leaf Scorch','مرض احتراق الأوراق','A symptom or disease where leaf margins or areas dry and look burned due to stress or pathogens.','عرض أو مرض تظهر فيه حواف الورقة أو أجزاء منها كأنها محترقة بسبب الإجهاد أو الممرضات.','Brown leaf margins, tip burn, interveinal browning, wilting, and dry brittle leaves.','اسمرار حواف الورقة، احتراق الأطراف، اسمرار بين العروق، ذبول، وأوراق جافة هشة.','Improve watering, reduce salt and heat stress, mulch, test roots and nutrients, and manage confirmed bacterial or fungal causes.','تحسين الري، تقليل الملوحة والحرارة، استخدام الملش، فحص الجذور والعناصر، ومعالجة السبب البكتيري أو الفطري المؤكد.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (74,'Leaf Mold','مرض عفن الأوراق','A fungal tomato disease caused by Passalora fulva, common in humid greenhouses.','مرض فطري في الطماطم تسببه Passalora fulva ويكثر في البيوت المحمية الرطبة.','Yellow spots on upper leaves, olive-brown mold underneath, leaf curling, drying, and defoliation.','بقع صفراء أعلى الأوراق، عفن زيتوني بني أسفلها، التفاف، جفاف، وتساقط الأوراق.','Ventilate greenhouses, reduce humidity, avoid leaf wetness, remove infected leaves, and use resistant varieties or fungicides.','تهوية البيوت المحمية، تقليل الرطوبة، تجنب بلل الأوراق، إزالة المصاب، واستخدام أصناف مقاومة أو مبيدات.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (75,'Septoria Leaf Spot','مرض تبقع أوراق السيبتوريا','A tomato leaf disease caused by Septoria lycopersici, usually starting on lower leaves.','مرض بقع أوراق الطماطم تسببه Septoria lycopersici ويبدأ غالباً بالأوراق السفلية.','Many small spots with grey centers and dark borders, black pycnidia, yellowing, and defoliation.','بقع صغيرة كثيرة بمراكز رمادية وحواف داكنة، نقاط سوداء، اصفرار، وتساقط الأوراق.','Remove lower infected leaves, mulch, avoid overhead irrigation, rotate crops, and apply fungicides preventively.','إزالة الأوراق السفلية المصابة، استخدام الملش، تجنب الري بالرش، تدوير المحصول، والرش الوقائي.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (76,'Spider Mites','مرض العنكبوت الأحمر ثنائي البقعة','A serious mite pest, Tetranychus urticae, that feeds on many crops under hot dry conditions.','آفة حلمية خطيرة هي Tetranychus urticae تتغذى على محاصيل كثيرة في الجو الحار الجاف.','Yellow stippling, webbing, bronzed leaves, leaf drop, and two-spotted mites on undersides.','تنقيط أصفر، خيوط عنكبوتية، تلون برونزي، تساقط أوراق، وحلم ذو بقعتين أسفل الورقة.','Increase humidity where practical, wash leaves, conserve predatory mites, rotate miticide modes of action, and avoid pesticide flare-ups.','زيادة الرطوبة عند الإمكان، غسل الأوراق، حماية الأعداء الحيوية، تدوير مجموعات مبيدات الأكاروس، وتجنب المبيدات التي تزيد الإصابة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (77,'Target Spot','مرض التبقع الهدف','A fungal disease causing target-like spots, common on tomato leaves and fruit in humid areas.','مرض فطري يسبب بقعاً تشبه الهدف ويصيب غالباً أوراق وثمار الطماطم في الرطوبة.','Brown circular lesions with concentric rings, yellowing, defoliation, and sunken fruit spots.','بقع بنية دائرية بحلقات متداخلة، اصفرار، تساقط أوراق، وبقع غائرة على الثمار.','Improve air flow, remove infected leaves, avoid overhead watering, rotate crops, and apply labeled fungicides.','تحسين التهوية، إزالة الأوراق المصابة، تجنب الري بالرش، تدوير المحصول، ورش مبيدات فطرية مسجلة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (78,'Tomato Yellow Leaf Curl Virus','مرض فيروس تجعد أوراق الطماطم الأصفر','A major tomato viral disease transmitted mainly by whiteflies.','مرض فيروسي مهم في الطماطم ينتقل أساساً بالذبابة البيضاء.','Upward leaf curling, yellow leaf margins, severe stunting, flower drop, and very low fruit set.','التفاف الأوراق للأعلى، اصفرار الحواف، تقزم شديد، تساقط الأزهار، وضعف شديد في العقد.','Use resistant hybrids, control whiteflies, use insect-proof nets, remove infected plants, and eliminate weed hosts.','استخدام هجن مقاومة، مكافحة الذبابة البيضاء، استخدام الشباك الحشرية، إزالة النباتات المصابة، وإزالة الأعشاب العائلة.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (79,'Tomato Mosaic Virus','مرض فيروس موزاييك الطماطم','A stable virus affecting tomato and related crops, spread by contact, tools, seed, and plant debris.','فيروس ثابت يصيب الطماطم ومحاصيل قريبة وينتقل بالملامسة والأدوات والبذور والمخلفات.','Mottled mosaic leaves, fern-like leaf narrowing, stunting, uneven fruit ripening, and internal browning.','تبرقش الأوراق، تضيق ورقي يشبه السرخس، تقزم، نضج غير منتظم للثمار، واسمرار داخلي.','Use resistant varieties, plant certified seed, disinfect tools and hands, remove infected plants, and avoid tobacco handling near plants.','استخدام أصناف مقاومة، زراعة بذور معتمدة، تعقيم الأدوات والأيدي، إزالة النباتات المصابة، وتجنب التعامل مع التبغ قرب النباتات.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (80,'Mosaic Virus','مرض فيروس الموزاييك','A general viral infection causing mosaic patterns and growth reduction in many crops.','عدوى فيروسية عامة تسبب نمط موزاييك وضعف نمو في محاصيل كثيرة.','Light and dark green mottling, leaf deformation, stunting, poor fruit quality, and reduced yield.','تداخل أخضر فاتح وداكن، تشوه أوراق، تقزم، ضعف جودة الثمار، ونقص الإنتاج.','Remove infected plants, manage insect vectors, use resistant cultivars, control weeds, and plant virus-free material.','إزالة النباتات المصابة، مكافحة النواقل، استخدام أصناف مقاومة، مكافحة الأعشاب، وزراعة مواد خالية من الفيروس.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (81,'Bacterial Canker','مرض التقرح البكتيري','A bacterial disease causing cankers, wilting, and fruit spotting, especially in tomato and woody plants.','مرض بكتيري يسبب تقرحات وذبولاً وبقع ثمار خاصة في الطماطم والنباتات الخشبية.','Leaf edge burn, wilting, stem cankers, vascular discoloration, bird-eye fruit spots, and plant decline.','احتراق حواف الأوراق، ذبول، تقرحات ساق، تلون الأوعية، بقع عين الطائر على الثمار، وتدهور النبات.','Use certified seed, hot-water treat seed where recommended, sanitize tools, remove infected plants, rotate crops, and avoid overhead irrigation.','استخدام بذور معتمدة، معاملة البذور بالماء الساخن عند التوصية، تعقيم الأدوات، إزالة المصاب، تدوير المحصول، وتجنب الري بالرش.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (82,'Healthy','سليم','The plant appears healthy with no visible signs of disease or damage, and no treatment is needed at this time.','النبتة تبدو سليمة ولا تظهر عليها أي علامات مرض أو ضرر، ولا تحتاج إلى علاج حاليًا.','Leaves appear normal and healthy.','الأوراق تبدو طبيعية وسليمة.','No treatment needed.','لا حاجة للعلاج.');
INSERT INTO `Diseases` (`DiseaseId`, `Name`, `NameAr`, `Description`, `DescriptionAr`, `Symptoms`, `SymptomsAr`, `Treatment`, `TreatmentAr`) VALUES (83,'Not Recognize','غير معروف','The uploaded image is not recognized as a supported plant image or the image is unclear.','الصورة المرفوعة غير معروفة أو لا تحتوي على نبات مدعوم أو أن الصورة غير واضحة بما يكفي للتحليل.','No plant disease symptoms were detected because the image could not be recognized correctly.','لم يتم اكتشاف أعراض مرضية لأن الصورة لم يتم التعرف عليها بشكل صحيح.','Please upload a clear image of a supported plant leaf or fruit with good lighting and focus.','يرجى رفع صورة واضحة لورقة أو ثمرة نبات مدعوم مع إضاءة جيدة وتركيز واضح.');
