INSERT INTO `Crops` (`CropId`, `Season`, `Name`, `NameArabic`, `PlantingTimeEn`, `PlantingTimeAr`, `GrowthPeriodEn`, `GrowthPeriodAr`, `DifficultyEn`, `DifficultyAr`, `UserId`, `ImageUrl`, `CreatedAt`) VALUES (22,'autumn','Cauliflower','القرنبيط','September, October','سبتمبر، أكتوبر','55-80 days','55-80 يوماً','Hard','صعب',1,'https://res.cloudinary.com/dbwncwexj/image/upload/v1776861821/Cauliflower_xuqvod.jpg','2026-04-07 21:41:14');
INSERT INTO `Crops` (`CropId`, `Season`, `Name`, `NameArabic`, `PlantingTimeEn`, `PlantingTimeAr`, `GrowthPeriodEn`, `GrowthPeriodAr`, `DifficultyEn`, `DifficultyAr`, `UserId`, `ImageUrl`, `CreatedAt`) VALUES (23,'autumn','Pomegranate','الرمان','August, September','أغسطس، سبتمبر','3-4 years','3-4 سنوات','Medium','متوسط',1,'https://res.cloudinary.com/dbwncwexj/image/upload/v1776861884/Pomegranate_crllli.jpg','2026-04-07 21:41:14');
INSERT INTO `Crops` (`CropId`, `Season`, `Name`, `NameArabic`, `PlantingTimeEn`, `PlantingTimeAr`, `GrowthPeriodEn`, `GrowthPeriodAr`, `DifficultyEn`, `DifficultyAr`, `UserId`, `ImageUrl`, `CreatedAt`) VALUES (24,'autumn','Apples','التفاح','August, September','أغسطس، سبتمبر','4-6 years','4-6 سنوات','Hard','صعب',1,'https://res.cloudinary.com/dbwncwexj/image/upload/v1776861818/Apples_zutyjr.jpg','2026-04-07 21:41:14');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (1,1,'Plant certified seed potatoes in cool weather, 8-12 cm deep, with 25-35 cm spacing.','ازرع درنات بطاطا معتمدة في طقس معتدل بعمق 8-12 سم وبمسافة 25-35 سم.','Water deeply 1-2 times weekly and keep moisture even during tuber formation.','اسقِ بعمق 1-2 مرة أسبوعيًا وحافظ على رطوبة منتظمة خلال تكوين الدرنات.','Needs 6-8 hours of direct sun.','تحتاج 6-8 ساعات شمس مباشرة.','Loose, well-drained soil rich in compost; hill soil around stems and feed with balanced fertilizer.','تربة مفككة جيدة الصرف وغنية بالكمبوست؛ قم بتكويم التربة حول السيقان مع تسميد متوازن.','Waterlogging.\nSkipping hilling.\nLate harvest after foliage collapse.','تغدق التربة بالماء.\nإهمال التكويم.\nتأخير الحصاد بعد تدهور المجموع الخضري.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (2,2,'Plant healthy seedlings in warm frost-free sites with 4-6 m spacing.','ازرع شتلات الكارامبولا في موقع دافئ خالٍ من الصقيع وبمسافة 4-6 متر.','Water regularly in establishment stage, then deep irrigation when topsoil dries.','اسقِ بانتظام في مرحلة التأسيس ثم ريّ عميق عند جفاف السطح.','Prefers full sun (6-8 hours).','تفضّل شمسًا كاملة (6-8 ساعات).','Well-drained fertile soil; apply organic matter and light balanced feeding during growth.','تربة خصبة جيدة الصرف؛ أضف مادة عضوية وتسميدًا متوازنًا خفيفًا أثناء النمو.','Cold exposure.\nPoor drainage.\nOver-pruning young trees.','التعرض للبرد.\nضعف الصرف.\nالتقليم الزائد للأشجار الصغيرة.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (3,3,'Plant dormant apricot saplings in late winter with good airflow and spacing.','ازرع شتلات المشمش الساكنة أواخر الشتاء مع تهوية جيدة ومسافات مناسبة.','Deep watering every 7-10 days in dry periods; reduce near harvest.','ريّ عميق كل 7-10 أيام في فترات الجفاف مع تقليل الري قرب الحصاد.','Needs full sun (7-8 hours).','يحتاج شمسًا كاملة (7-8 ساعات).','Well-drained loam, pH near neutral; feed in early spring and after fruit set.','تربة طميية جيدة الصرف وحموضة قريبة من المتعادل؛ سمّد في بداية الربيع وبعد العقد.','Late frost damage.\nOverwatering roots.\nSkipping pruning.','أضرار الصقيع المتأخر.\nالإفراط في الري.\nإهمال التقليم.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (4,4,'Sow soybean after soil warms above 15C at 3-5 cm depth.','ازرع فول الصويا بعد دفء التربة فوق 15°م بعمق 3-5 سم.','Moderate regular watering, especially at flowering and pod filling.','ريّ معتدل منتظم خاصة وقت الإزهار وامتلاء القرون.','Needs 6-8 hours of direct sun.','يحتاج 6-8 ساعات شمس مباشرة.','Well-drained soil; inoculate seed when needed and avoid heavy nitrogen.','تربة جيدة الصرف؛ يمكن تلقيح البذور بكتيريا نافعة وتجنب الإفراط بالنيتروجين.','Water stress at flowering.\nDense planting.\nExcess nitrogen fertilizer.','العطش وقت الإزهار.\nالزراعة الكثيفة.\nالإفراط في التسميد النيتروجيني.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (5,5,'Sow directly in cool weather at 1-2 cm depth with short intervals for continuous harvest.','ازرع الفجل مباشرة في الجو المعتدل بعمق 1-2 سم وعلى دفعات متقاربة للحصاد المستمر.','Keep soil evenly moist with light frequent watering.','حافظ على رطوبة متوازنة بريّ خفيف متكرر.','Prefers 4-6 hours sun.','يفضل 4-6 ساعات شمس.','Loose fertile soil without stones; light feeding is enough.','تربة مفككة خصبة وخالية من الحصى؛ يكفي تسميد خفيف.','Irregular watering.\nOvercrowding.\nLate harvest causing pithy roots.','الري غير المنتظم.\nالزراعة المتزاحمة.\nتأخير الحصاد مما يسبب جذورًا ليفية.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (6,6,'Plant grafted mango trees in warm sunny areas with wide spacing.','ازرع شتلات مانجو مطعمة في مكان دافئ مشمس وبمسافات واسعة.','Deep watering during establishment; reduce frequency for mature trees.','ري عميق خلال التأسيس ثم تقليل عدد الريات للأشجار البالغة.','Needs full sun (8+ hours).','تحتاج شمسًا كاملة (8+ ساعات).','Well-drained soil with organic matter; balanced feeding with potassium support at fruiting.','تربة جيدة الصرف مع مادة عضوية؛ تسميد متوازن مع دعم البوتاسيوم وقت الإثمار.','Waterlogging.\nCold exposure.\nHeavy pruning at wrong time.','تغدق التربة.\nالتعرض للبرد.\nالتقليم الشديد في توقيت غير مناسب.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (7,7,'Sow peas directly in cool weather at 3-4 cm depth.','تزرع البازلاء في الجو البارد مباشرة في التربة بعمق 3-4 سم.','Moderate regular watering; increase during flowering.','ري منتظم معتدل، وتزداد الحاجة للماء وقت الإزهار.','Direct sun for about 5-7 hours.','شمس مباشرة 5-7 ساعات.','Well-drained soil; light feeding only and avoid high nitrogen.','تربة جيدة الصرف؛ تسميد خفيف فقط وتجنب النيتروجين العالي.','Planting in high heat.\nToo much nitrogen fertilizer.\nNo support for climbing varieties.','الزراعة في حرارة مرتفعة.\nالإفراط في التسميد النتروجيني.\nضعف الدعامة.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (8,8,'Grow lemon in warm sunny sites with frost protection.','تزرع الليمون في مكان دافئ ومشمس مع حماية من الصقيع.','Deep regular watering in summer, reduced in winter; avoid standing water.','ري عميق منتظم صيفًا، وأقل شتاءً، مع منع ركود الماء حول الجذور.','6-8 hours of direct sun.','6-8 ساعات شمس مباشرة.','Light, well-drained soil with pH around 6-7; feed with citrus fertilizer in split doses.','تربة خفيفة جيدة الصرف وحموضة 6-7 تقريبًا؛ سماد حمضيات على دفعات.','Frost injury.\nExcess irrigation.\nPoor drainage.','تجمد الشتلات.\nالري المفرط.\nضعف الصرف.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (9,9,'Grow lettuce in mild weather, shallow sowing with 20-30 cm spacing.','ازرع الخس في جو معتدل، بعمق خفيف ومسافة 20-30 سم.','Keep soil consistently moist with light, frequent watering.','يحافظ على أوراق طرية مع ري خفيف متكرر ومنتظم.','4-6 hours sun; provide light shade in hot weather.','4-6 ساعات شمس، ويفضل ظلًا خفيفًا في الحر.','Fertile, moisture-retentive but well-drained soil; light nitrogen-rich feeding every two weeks.','تربة خصبة ورطبة جيدة الصرف؛ تسميد خفيف غني بالنيتروجين كل أسبوعين.','High heat stress.\nAllowing soil to dry out.\nLate harvest causing bitterness.','تعريضه لحر شديد.\nجفاف التربة.\nتأخير الحصاد حتى المرارة.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (10,10,'Plant orange trees in warm soil and full sun.','تزرع شتلات البرتقال في تربة دافئة ومكان مشمس.','Deep regular watering; reduce frequency in cool weather.','ري عميق منتظم مع تقليل الري في الأجواء الباردة.','6-8 hours direct sun.','6-8 ساعات شمس مباشرة.','Well-drained soil enriched with organic matter; apply citrus fertilizer 2-3 times yearly.','تربة جيدة الصرف غنية بالمادة العضوية؛ تسميد حمضيات متوازن 2-3 مرات سنويًا.','Constant heavy watering.\nGrowing in shade.\nSkipping hygiene pruning.','الري الثقيل المستمر.\nالزراعة في ظل.\nإهمال التقليم الصحي.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (11,11,'Plant healthy runners/crowns in cool weather with crowns above soil line.','ازرع شتلات الفراولة السليمة في جو معتدل مع بقاء قلب النبات فوق سطح التربة.','Frequent light watering; keep moisture stable during flowering and fruiting.','ري خفيف متكرر مع ثبات الرطوبة خلال الإزهار والإثمار.','Needs 6-8 hours of sun.','تحتاج 6-8 ساعات شمس.','Well-drained rich soil with mulch; balanced feeding and calcium support when needed.','تربة خصبة جيدة الصرف مع تغطية عضوية؛ تسميد متوازن ودعم بالكالسيوم عند الحاجة.','Water on leaves at night.\nOvercrowding.\nPoor hygiene of old leaves.','بلل الأوراق ليلًا.\nالزراعة المتزاحمة.\nإهمال إزالة الأوراق القديمة.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (12,12,'Plant guava seedlings in warm sunny sites with 4-5 m spacing.','ازرع شتلات الجوافة في موقع دافئ مشمس وبمسافة 4-5 متر.','Deep watering at intervals; increase in hot dry periods.','ري عميق على فترات مع زيادة الري في الحر والجفاف.','Prefers full sun (6-8 hours).','تفضّل شمسًا كاملة (6-8 ساعات).','Well-drained soil with organic matter; apply balanced fertilizer 2-3 times per season.','تربة جيدة الصرف مع مادة عضوية؛ سماد متوازن 2-3 مرات في الموسم.','Ignoring pruning.\nOverwatering.\nLate pest control.','إهمال التقليم.\nالري الزائد.\nتأخر مكافحة الآفات.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (13,13,'Start seeds 6-8 weeks before last frost and transplant after temperatures stabilize. Plant deep with 40-60 cm spacing.','ابدأ البذور قبل 6-8 أسابيع من آخر صقيع ثم انقل الشتلات بعد استقرار الحرارة. ازرع بعمق مع ترك 40-60 سم بين النباتات.','Water deeply 2-3 times weekly with steady soil moisture. Avoid wetting leaves to reduce fungal disease.','اسقِ بعمق 2-3 مرات أسبوعيًا مع تثبيت الرطوبة. تجنب تبليل الأوراق لتقليل الأمراض الفطرية.','Needs 6-8 hours of direct sun daily.','تحتاج 6-8 ساعات شمس مباشرة يوميًا.','Well-drained loamy soil rich in compost, pH 6.0-6.8. Apply balanced fertilizer at planting, then shift to higher potassium at flowering/fruiting.','تربة خفيفة جيدة التصريف وغنية بالكمبوست، pH بين 6.0 و6.8. أضف سمادًا متوازنًا عند الزراعة ثم زِد البوتاسيوم عند بداية الإزهار والإثمار.','Irregular watering causing fruit cracking.\nExcess nitrogen that boosts leaves over fruit.\nPoor airflow around plants.','الري غير المنتظم الذي يسبب تشقق الثمار.\nالإفراط في النيتروجين على حساب الثمار.\nالزراعة في مكان سيئ التهوية.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (14,14,'Transplant once temperatures are warm, spacing plants 50-60 cm.','ازرع الشتلات بعد ارتفاع الحرارة، واترك مسافة 50-60 سم بين النباتات.','Deep watering 2-3 times weekly with even moisture.','ري عميق 2-3 مرات أسبوعيًا مع ثبات الرطوبة.','Prefers 6-8 hours of direct sunlight.','يفضل 6-8 ساعات شمس مباشرة.','Rich, well-drained soil with ample organic matter. Balanced feeding every 2-3 weeks during fruiting.','تربة غنية جيدة الصرف مع مادة عضوية مرتفعة. تسميد متوازن كل 2-3 أسابيع خلال الإثمار.','Exposure to early cold.\nOverwatering.\nLetting fruits overmature before harvest.','البرودة المبكرة.\nالري الزائد.\nترك الثمار تكبر كثيرًا قبل القطف.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (15,15,'Sow after soil warms (18C+) at 2-3 cm depth with 40-50 cm spacing.','ازرع بعد دفء التربة (18 م° فأعلى) بعمق 2-3 سم مع مسافة 40-50 سم بين النباتات.','Cucumber yields best with consistent moisture, about 3-4 waterings weekly in warm weather.','يحافظ الخيار على إنتاج جيد مع ري ثابت 3-4 مرات أسبوعيًا حسب الحرارة.','Requires 6-8 hours of direct sun.','يحتاج 6-8 ساعات شمس مباشرة.','Fertile, well-drained soil with high organic matter. Feed with balanced fertilizer every 2-3 weeks during growth and bloom.','تربة خصبة جيدة الصرف وغنية بالمادة العضوية. سماد متوازن كل 2-3 أسابيع خلال النمو والإزهار.','Alternating drought and overwatering.\nDense planting without airflow.\nLate harvesting that slows new fruiting.','تعطيش النبات ثم إغراقه بالماء.\nالزراعة الكثيفة بدون تهوية.\nتأخير القطف مما يقلل الإنتاج.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (16,16,'Start pepper seedlings early and transplant after cool weather passes, spacing 40-50 cm.','ابدأ شتلات الفلفل مبكرًا وانقلها بعد زوال البرودة، مع تباعد 40-50 سم.','Water when top 3 cm dries, usually 2-3 times weekly.','ري منتظم عندما يجف أول 3 سم من التربة، عادة 2-3 مرات أسبوعيًا.','Needs 6-8 hours of direct sun daily.','يحتاج شمسًا مباشرة 6-8 ساعات يوميًا.','Warm, well-drained loam, pH around 6.0-6.8. Light balanced feeding, with extra potassium at fruit set.','تربة خفيفة دافئة جيدة الصرف، pH حوالي 6.0-6.8. جرعات خفيفة متوازنة، مع دعم البوتاسيوم وقت العقد.','Transplanting before soil warms.\nOverwatering roots.\nToo much shade.','الزراعة المبكرة قبل دفء التربة.\nالإفراط في الري.\nتظليل النبات أكثر من اللازم.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (17,17,'Plant corn in blocks (not a single row) to improve pollination, at 3-5 cm depth.','ازرع الذرة في كتل (وليس صفًا واحدًا) لتحسين التلقيح، بعمق 3-5 سم.','Needs deep regular watering, especially at tasseling and ear fill.','تحتاج ريًا عميقًا منتظمًا خاصة أثناء التزهير وتعبئة الحبوب.','8+ hours of direct sunlight.','8 ساعات شمس مباشرة أو أكثر.','Deep, well-drained soil rich in organic matter. Requires staged nitrogen feeding.','تربة عميقة جيدة التصريف وغنية بالمواد العضوية. تحتاج تغذية جيدة بالنيتروجين على مراحل.','Planting in one row only.\nWater stress during flowering.\nPoor stand density.','الزراعة في صف واحد.\nالعطش أثناء التزهير.\nكثافة زراعة ضعيفة.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (18,18,'Plant after warm weather arrives, in warm soil with wide spacing for vine spread.','تزرع بعد دفء الجو في تربة دافئة، مع مساحات واسعة للتمدد.','Deep regular watering early; reduce near ripening for better flavor and less cracking.','ري عميق منتظم في البداية، ثم خفّف قرب النضج لتحسين الطعم وتقليل التشقق.','Needs strong direct sunlight, around 8 hours.','تحتاج شمسًا مباشرة قوية 8 ساعات تقريبًا.','Light sandy-loam, well drained. Use balanced fertilizer early, then emphasize potassium during fruit development.','تربة رملية خفيفة جيدة الصرف. سماد متوازن أولًا، ثم دعم بالبوتاسيوم عند تكوين الثمار.','Overcrowding.\nOverwatering near ripening.\nPoor drainage.','الزراعة بكثافة.\nالري الزائد وقت النضج.\nسوء الصرف.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (19,19,'Plant olive trees in very sunny locations with excellent drainage.','ازرع الزيتون في موقع مشمس جدًا وتربة جيدة الصرف.','Deep, infrequent irrigation; established olives tolerate moderate drought.','ري عميق متباعد؛ الزيتون يتحمل الجفاف النسبي بعد التأسيس.','8+ hours of direct sunlight.','8 ساعات شمس مباشرة أو أكثر.','Medium to light well-drained soils; avoid high salinity. Light organic/balanced feeding in spring.','تربة متوسطة إلى خفيفة التصريف، وتجنب الملوحة العالية. تسميد عضوي/متوازن خفيف في الربيع.','Overwatering.\nToo much shade.\nNeglecting pruning/maintenance.','الري الزائد.\nالظل.\nإهمال التقليم والصيانة.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (20,20,'Plant pumpkin in warm soil with wide spacing since vines spread aggressively.','ازرع القرع في تربة دافئة ومساحة واسعة لأن النبات زاحف.','Deep watering 1-2 times weekly depending on heat and soil.','ري عميق 1-2 مرة أسبوعيًا حسب الحرارة والتربة.','6-8 hours of direct sunlight.','6-8 ساعات شمس مباشرة.','Very compost-rich, well-drained soil. Regular feeding, with higher potassium at fruit set.','تربة غنية جدًا بالكمبوست وجيدة الصرف. تسميد منتظم مع زيادة البوتاسيوم وقت تكوين الثمار.','Insufficient spacing.\nInconsistent watering.\nIgnoring pest pressure.','ضيق المساحة.\nالري المتذبذب.\nإهمال مراقبة الآفات.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (21,21,'Plant grape vines in a sunny site with a strong trellis and regular pruning.','تزرع شتلات العنب في موقع مشمس مع تعريشة/دعامة قوية وتقليم منتظم.','Moderate irrigation: water deeply, then allow slight surface drying between irrigations.','الري معتدل؛ اسقِ بعمق ثم اترك سطح التربة يجف قليلًا بين الريات.','Prefers 7-8 hours of direct sun.','يفضل 7-8 ساعات شمس مباشرة.','Well-drained soil; avoid prolonged root saturation. Balanced nutrition early season; avoid excess nitrogen.','تربة جيدة الصرف، وتجنب الغمر حول الجذور. تسميد متوازن في بداية الموسم مع عدم المبالغة في النيتروجين.','Skipping pruning.\nOverirrigation.\nPoor canopy airflow.','إهمال التقليم.\nزيادة الري.\nضعف التهوية بين الأفرع.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (22,22,'Transplant cauliflower seedlings in cool weather with 45-60 cm spacing.','ازرع شتلات القرنبيط في الجو المعتدل بمسافة 45-60 سم.','Keep soil steadily moist, especially during head formation.','حافظ على رطوبة ثابتة للتربة خاصة أثناء تكوين الرأس.','Needs 5-7 hours of sun.','يحتاج 5-7 ساعات شمس.','Fertile soil rich in compost; balanced feeding with boron/calcium support if deficient.','تربة خصبة غنية بالكمبوست؛ تسميد متوازن مع دعم البورون/الكالسيوم عند النقص.','Heat stress.\nWater stress.\nDelayed harvest after head loosening.','إجهاد الحرارة.\nعدم انتظام الري.\nتأخير الحصاد بعد تفتح الرأس.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (23,23,'Plant pomegranate in warm sunny sites with moderate spacing.','ازرع الرمان في مواقع دافئة مشمسة مع مسافات مناسبة.','Deep watering at intervals; reduce excessive irrigation near ripening.','ري عميق على فترات مع تجنب زيادة الري قرب النضج.','Needs full sun (6-8+ hours).','يحتاج شمسًا كاملة (6-8+ ساعات).','Well-drained soil; organic matter addition and seasonal balanced fertilizer are recommended.','تربة جيدة الصرف؛ يوصى بإضافة مادة عضوية وتسميد متوازن موسمي.','Overwatering.\nIgnoring pruning/suckers.\nLate pest management.','الري الزائد.\nإهمال التقليم والسرطانات.\nتأخر مكافحة الآفات.','2026-04-24 16:10:17.000000');
INSERT INTO `cropdetails` (`CropDetailsId`, `CropId`, `PlantingMethodEn`, `PlantingMethodAr`, `WateringPlanEn`, `WateringPlanAr`, `SunlightEn`, `SunlightAr`, `SoilAndFertilizingEn`, `SoilAndFertilizingAr`, `AvoidMistakesEn`, `AvoidMistakesAr`, `CreatedAt`) VALUES (24,24,'Plant grafted apple saplings in winter dormancy with proper pollinator planning.','ازرع شتلات التفاح المطعمة في سكون الشتاء مع مراعاة وجود صنف مُلَقِّح.','Deep watering every 7-10 days in dry periods; avoid overwatering.','ري عميق كل 7-10 أيام في فترات الجفاف مع تجنب الإفراط في الري.','Needs full sun (7-8 hours).','يحتاج شمسًا كاملة (7-8 ساعات).','Well-drained loam with organic matter; seasonal balanced fertilization and pruning are essential.','تربة طميية جيدة الصرف مع مادة عضوية؛ تسميد موسمي متوازن مع تقليم دوري.','Poor pollination.\nOvercrowded canopy.\nSkipping disease prevention.','ضعف التلقيح.\nتزاحم الأفرع.\nإهمال الوقاية من الأمراض.','2026-04-24 16:10:17.000000');
